import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"发射队列与唤醒选择","description":"","frontmatter":{"title":"发射队列与唤醒选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/issue-queue-wakeup.md","filePath":"cs/issue-queue-wakeup.md","lastUpdated":1789023840000}'),u={name:"cs/issue-queue-wakeup.md"};function c(h,a,m,A,B,_){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="发射队列与唤醒选择" tabindex="-1">发射队列与唤醒选择 <a class="header-anchor" href="#发射队列与唤醒选择" aria-label="Permalink to &quot;发射队列与唤醒选择&quot;">​</a></h1><div class="epigraph"><p>保留站变成一张按就绪位挑选的队列：结果写回时用标签匹配把等待者唤醒，选择逻辑再在同一拍里挑出能进 ALU 的那几条。</p><footer>—— 据 Palacharla, Jouppi, and Smith, ISCA 1997；Tomasulo, IBM Journal 1967 整理</footer></div><p><a href="/cs/prf-free-list">上一课</a>让物理寄存器带就绪位。<a href="/cs/tomasulo">Tomasulo</a> 的 CDB 广播是唤醒的语义。本课不重讲自由列表。缺口是：<strong>把「操作数齐」变成每拍可调度的硬件——唤醒（wake-up）与选择（select），以及这套逻辑如何限制时钟。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窗口里几十条指令，每拍可能写回 2–4 个物理号。要在下一拍让依赖它们的指令可发，比较器数量随「队列项 × 写回宽度」涨。选哪一条进有限的 ALU 端口：最老优先以逼近程序序、减少无谓冲刷，但比较年龄又加一级逻辑。缺口不是再加物理寄存器，而是<strong>在频率可接受的前提下做匹配 + 仲裁</strong>。</p><p><span class="marginnote">Palacharla 等把超标量的复杂度瓶颈钉在发射窗口：增大窗口提高 ILP，但唤醒/选择的延迟会逼你降频，净性能可能掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发射队列（IQ / RS）：每项存操作码、源物理号、就绪位、目的物理号。写回总线带物理号；每项比较，匹配则置就绪。两源都就绪则参加选择：按年龄或按类型把最多 \\(W\\) 条送到对应功能单元，占用端口。</p>',8)),(e(),n(d,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WB%5B%22%E5%86%99%E5%9B%9E%E7%89%A9%E7%90%86%E5%8F%B7%22%5D%20--%3E%20WU%5B%22%E9%98%9F%E5%88%97%E5%86%85%E6%A0%87%E7%AD%BE%E5%8C%B9%E9%85%8D%22%5D%0A%20%20WU%20--%3E%20RDY%5B%22%E6%BA%90%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20RDY%20--%3E%20SEL%5B%22%E6%8C%89%E5%B9%B4%E9%BE%84%2F%E7%B1%BB%E5%9E%8B%E9%80%89%E6%8B%A9%22%5D%0A%20%20SEL%20--%3E%20EX%5B%22%E9%80%81%E5%85%A5%20ALU%20%2F%20AGU%22%5D%0A%20%20SEL%20--%3E%20STALL%5B%22%E7%AB%AF%E5%8F%A3%E4%B8%8D%E5%A4%9F%E5%88%99%E7%95%99%E5%9C%A8%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>load 的就绪来自 cache 命中或转发，延迟可变，所以 IQ 必须允许「发出去又发现 miss 再重发」或「等命中再发」两种设计；细节交给 LSQ 课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">CPI</a> 的停顿项多了一类：窗口已满但选择逻辑看得到的就绪指令少于端口——ILP 不够；或就绪很多但端口不够——结构冒险。深窗口提高前者、恶化后者与时钟。</p><p>推测：IQ 项带着 ROB 序号，冲刷时按序号作废，与<a href="/cs/speculation-recovery">恢复</a>同一套年轻指令丢弃。被选择但尚未写回的指令若所在路径冲刷，功能单元结果作废。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 load 越过未算完地址的 store 合法化，那是下一课消歧。也不引入宏融合后「一条 IQ 项对应两条 ISA 指令」——那是前端课。选择逻辑的具体电路（前缀树找最老就绪）不展开。</p><p>后课默认：就绪即竞争端口；年龄优先是常见策略。内存相关不能只靠寄存器标签，因为地址在 AGU 之后才有。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>唤醒是物理号匹配，选择是端口仲裁；二者限制窗口与频率。</li><li>冲刷按 ROB 序号作废 IQ 项。</li><li>访存相关要 LSQ，下一课才消歧。</li><li>出处：Palacharla, Jouppi, Smith, <em>ISCA</em>, 1997；Tomasulo, 1967。</li></ul>',9))])}const T=s(u,[["render",c]]);export{S as __pageData,T as default};
